return [{ json: {
  order_id: 'ORD-1042',
  customer: { name: 'Sneha Kapoor', state: 'Delhi', email: 'sneha@example.com' },
  coupon: 'NEW10',
  items: [
    { sku: 'TSHIRT-BLK', name: 'Black T-shirt', qty: 2, price: 799, gst: 12 },
    { sku: 'MUG-01', name: 'Coffee Mug', qty: 1, price: 349, gst: 18 },
    { sku: 'CAP-RED', name: 'Red Cap', qty: 3, price: 299, gst: 12 }
  ]
} }];

const round = (n) => Math.round(n * 100) / 100;
return $input.all().map(({ json: o }) => {
  const discountPct = o.coupon === 'NEW10' ? 10 : 0;
  const lines = o.items.map((it) => {
    const base = it.qty * it.price;
    const disc = base * discountPct / 100;
    const taxable = base - disc;
    const tax = taxable * it.gst / 100;
    return { ...it, base, discount: round(disc), taxable: round(taxable), cgst: round(tax / 2), sgst: round(tax / 2), total: round(taxable + tax) };
  });
  const sum = (k) => round(lines.reduce((a, l) => a + l[k], 0));
  return { json: {
    invoice_no: 'INV-' + o.order_id.split('-')[1],
    date: new Date().toISOString().slice(0, 10),
    customer: o.customer,
    lines,
    subtotal: sum('base'), discount: sum('discount'), cgst: sum('cgst'), sgst: sum('sgst'),
    grand_total: Math.round(sum('total'))
  } };
});
